const fs = require('fs');
const body = $input.first().json.body || $input.first().json;
const data = body.data || {};

const remoteJid = data.key?.remoteJid || '';
const senderName = data.pushName || 'الزائر الكريم';
const text = data.text || '';
const messageType = data.messageType || 'text';
const mediaBase64 = data.mediaBase64 || null;
const mimeType = data.mimeType || null;

if (!text && !mediaBase64) return [];

// First contact check
const seenPath = '/tmp/seen_users.json';
let seen = {};
try { seen = JSON.parse(fs.readFileSync(seenPath, 'utf8')); } catch(e) {}

if (!seen[remoteJid]) {
  seen[remoteJid] = new Date().toISOString();
  fs.writeFileSync(seenPath, JSON.stringify(seen, null, 2));
  try {
    await fetch('http://YOUR_BAILEYS_IP:3000/send', {
      method: 'POST',
      headers: {'Content-Type': 'application/json', 'x-secret': 'masjid-secret-2024'},
      body: JSON.stringify({
        number: remoteJid,
        text: 'السلام عليكم ورحمة الله وبركاته 🕌\nأهلاً وسهلاً بك في بوت مسجدنا!\nيمكنك سؤالي عن أوقات الصلاة والأنشطة والخدمات وأي شيء يخص المسجد.'
      })
    });
  } catch(e) {}
}

return [{ json: { phone: remoteJid, remoteJid, text, senderName, messageType, mediaBase64, mimeType } }];

const doc = $input.first().json;
let docText = '';

if (doc.body?.content) {
  for (const el of doc.body.content) {
    if (el.paragraph?.elements) {
      for (const e of el.paragraph.elements) {
        if (e.textRun?.content) docText += e.textRun.content;
      }
    }
  }
}

const msg = $('Get Phone and Message').item.json;
return [{ json: { ...msg, docContent: docText.trim() } }];

